function swapAdjectives(sentence) {
  const words = sentence.split(' ');
  const adjectivePattern = /^(adjective|adjectival)\b/; // Simple pattern to identify adjectives (expand for more nuanced detection if needed)
  let adjectives = words.filter(word => adjectivePattern.test(word.toLowerCase())); 

  if (adjectives.length >= 2) {
    // Swap the positions of the first two adjectives
    const swappedWords = [ ...words.slice(0, words.indexOf(adjectives[0])), adjectives[1], adjectives[0], ...words.slice(words.indexOf(adjectives[0]) + 1) ];
    return swappedWords.join(' ');
  } else {
    return sentence; // Handle cases with less than two adjectives
  }
}

// Example usage:
const originalSentence = "Beautiful green trees are in the park";
const modifiedSentence = swapAdjectives(originalSentence);
console.log(modifiedSentence); // Output: Green beautiful trees are in the park 
```

