```javascript
const axios = require('axios'); // Assuming you have Axios for API calls

async function postToSlack(text, channelId, slackToken) {
  try {
    const payload = {
      channel: channelId,
      text: text
    };

    // Construct the Slack API endpoint URL with token for authorization
    const url = `https://slack.com/api/chat.postMessage?token=${slackToken}`;

    const response = await axios.post(url, payload);

    // Analyze response for success (status code and 'ok' field)
    if (response.status === 200 && response.data.ok) {
      console.log(`Message "${text}" successfully posted to channel ${channelId}`);
      return { success: true, message: response.data }; // Enhanced verbosity with details
    } else {
      console.error(`Error posting to Slack: ${JSON.stringify(response.data)}`);
      return { success: false, error: response.data }; 
    }
  } catch (error) {
    console.error(`Critical Slack API error: ${error.message}`);
    return { success: false, error: error.message }; 
  }
}

// Example Usage:
postToSlack("Hello from my JavaScript function!", "YOUR_CHANNEL_ID", "YOUR_SLACK_BOT_TOKEN")
  .then(result => console.log(result)); 
```

