```matlab
% 1. Load and Preprocess Image
input_image = imread('image.jpg');
gray_image = rgb2gray(input_image); 

% 2. Gaussian Smoothing (Noise Reduction)
%   - Choose a suitable sigma value (standard deviation) for your noise level. 
%     A common starting point is sigma = 1.5  
sigma = 1.5; 
gaussian_filtered = imgaussfilt(gray_image, sigma); % Apply Gaussian filter

% 3. Sobel Operator Application
sobel_x = [-1 0 1; -2 0 2; -1 0 1]; 
sobel_y = [-1 -2 -1; 0 0 0; 1 2 1];

edge_image_x = conv2(double(gaussian_filtered), sobel_x, 'same'); 
edge_image_y = conv2(double(gaussian_filtered), sobel_y, 'same');

% 4. Edge Magnitude Calculation
edge_image = sqrt(edge_image_x.^2 + edge_image_y.^2); % Combine gradients

% 5. Thresholding (Optional but Recommended)
%   - Enhance contrast and clarity by setting a threshold to emphasize prominent edges.
threshold = 0.15 * max(edge_image(:));  % Adjust this threshold as needed
binary_edges = edge_image > threshold; 

% 6. Visualization
imshow(binary_edges, []); % Display binary edge map (black/white)
title('Edges after Gaussian Filtering and Sobel');

```

